## 3. iOS

### `NativeLocalStorage/RCTNativeLocalStorage.h`

```objc
//  RCTNativeLocalStorage.h
//  TurboModuleExample

#import <Foundation/Foundation.h>
#import <NativeLocalStorageSpec/NativeLocalStorageSpec.h>

NS_ASSUME_NONNULL_BEGIN

@interface RCTNativeLocalStorage : NSObject
@interface RCTNativeLocalStorage : NSObject <NativeLocalStorageSpec>
@end
```

The page shows the template line `@interface RCTNativeLocalStorage : NSObject` and then the updated line with `<NativeLocalStorageSpec>`. The intended header keeps only the second line. The page also has no matching `NS_ASSUME_NONNULL_END`.

### `NativeLocalStorage/RCTNativeLocalStorage.mm`

```objc
//  RCTNativeLocalStorage.m
//  TurboModuleExample

#import "RCTNativeLocalStorage.h"

static NSString *const RCTNativeLocalStorageKey = @"local-storage";

@interface RCTNativeLocalStorage()
@property (strong, nonatomic) NSUserDefaults *localStorage;
@end

@implementation RCTNativeLocalStorage

- (id) init {
  if (self = [super init]) {
    _localStorage = [[NSUserDefaults alloc] initWithSuiteName:RCTNativeLocalStorageKey];
  }
  return self;
}

- (std::shared_ptr<facebook::react::TurboModule>)getTurboModule:(const facebook::react::ObjCTurboModule::InitParams &)params {
  return std::make_shared<facebook::react::NativeLocalStorageSpecJSI>(params);
}

- (NSString * _Nullable)getItem:(NSString *)key {
  return [self.localStorage stringForKey:key];
}

- (void)setItem:(NSString *)value
          key:(NSString *)key {
  [self.localStorage setObject:value forKey:key];
}

- (void)removeItem:(NSString *)key {
  [self.localStorage removeObjectForKey:key];
}

- (void)clear {
  NSDictionary *keys = [self.localStorage dictionaryRepresentation];
  for (NSString *key in keys) {
    [self removeItem:key];
  }
}

+ (NSString *)moduleName{
  return @"NativeLocalStorage";
}

@end
```

### Registration on iOS

- The iOS page contains no `RCT_EXPORT_MODULE` macro and no AppDelegate code.
- Registration is done only through `codegenConfig` `ios.modulesProvider`, which maps `"NativeLocalStorage"` to `"RCTNativeLocalStorage"`.
- The `.mm` supplies `+ moduleName` (returns `@"NativeLocalStorage"`) and `getTurboModule:`, which returns `std::make_shared<facebook::react::NativeLocalStorageSpecJSI>(params)`.

## 4. Android

### `android/app/src/main/java/com/nativelocalstorage/NativeLocalStorageModule.kt`

```kotlin
package com.nativelocalstorage

import android.content.Context
import android.content.SharedPreferences
import com.nativelocalstorage.NativeLocalStorageSpec
import com.facebook.react.bridge.ReactApplicationContext

class NativeLocalStorageModule(reactContext: ReactApplicationContext) : NativeLocalStorageSpec(reactContext) {

  override fun getName() = NAME

  override fun setItem(value: String, key: String) {
    val sharedPref = getReactApplicationContext().getSharedPreferences("my_prefs", Context.MODE_PRIVATE)
    val editor = sharedPref.edit()
    editor.putString(key, value)
    editor.apply()
  }

  override fun getItem(key: String): String? {
    val sharedPref = getReactApplicationContext().getSharedPreferences("my_prefs", Context.MODE_PRIVATE)
    val username = sharedPref.getString(key, null)
    return username.toString()
  }

  override fun removeItem(key: String) {
    val sharedPref = getReactApplicationContext().getSharedPreferences("my_prefs", Context.MODE_PRIVATE)
    val editor = sharedPref.edit()
    editor.remove(key)
    editor.apply()
  }

  override fun clear() {
    val sharedPref = getReactApplicationContext().getSharedPreferences("my_prefs", Context.MODE_PRIVATE)
    val editor = sharedPref.edit()
    editor.clear()
    editor.apply()
  }

  companion object {
    const val NAME = "NativeLocalStorage"
  }
}
```

The `getItem` body `return username.toString()` is in the docs as written. It turns a missing key into the string `"null"` rather than returning `null`.

### `android/app/src/main/java/com/nativelocalstorage/NativeLocalStoragePackage.kt`

```kotlin
package com.nativelocalstorage

import com.facebook.react.BaseReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.module.model.ReactModuleInfo
import com.facebook.react.module.model.ReactModuleInfoProvider

class NativeLocalStoragePackage : BaseReactPackage() {

  override fun getModule(name: String, reactContext: ReactApplicationContext): NativeModule? =
    if (name == NativeLocalStorageModule.NAME) {
      NativeLocalStorageModule(reactContext)
    } else {
      null
    }

  override fun getReactModuleInfoProvider() = ReactModuleInfoProvider {
    mapOf(
      NativeLocalStorageModule.NAME to ReactModuleInfo(
        name = NativeLocalStorageModule.NAME,
        className = NativeLocalStorageModule.NAME,
        canOverrideExistingModule = false,
        needsEagerInit = false,
        isCxxModule = false,
        isTurboModule = true
      )
    )
  }
}
```

### MainApplication registration

The page gives the file path as `android/app/src/main/java/com/turobmoduleexample/MainApplication.kt`. The path spells "turobmoduleexample" (sic), and the declared package is `com.inappmodule`, so the path and package do not match in the docs.

```kotlin
package com.inappmodule

import android.app.Application
import com.facebook.react.PackageList
import com.facebook.react.ReactApplication
import com.facebook.react.ReactHost
import com.facebook.react.ReactNativeHost
import com.facebook.react.ReactPackage
import com.facebook.react.defaults.DefaultNewArchitectureEntryPoint.load
import com.facebook.react.defaults.DefaultReactHost.getDefaultReactHost
import com.facebook.react.defaults.DefaultReactNativeHost
import com.facebook.soloader.SoLoader
import com.nativelocalstorage.NativeLocalStoragePackage

class MainApplication : Application(), ReactApplication {

  override val reactNativeHost: ReactNativeHost =
      object : DefaultReactNativeHost(this) {
        override fun getPackages(): List<ReactPackage> =
            PackageList(this).packages.apply {
              // Packages that cannot be autolinked yet can be added manually here, for example:
              // add(MyReactNativePackage())
              add(NativeLocalStoragePackage())
            }

        override fun getJSMainModuleName(): String = "index"

        override fun getUseDeveloperSupport(): Boolean = BuildConfig.DEBUG

        override val isNewArchEnabled: Boolean = BuildConfig.IS_NEW_ARCHITECTURE_ENABLED
        override val isHermesEnabled: Boolean = BuildConfig.IS_HERMES_ENABLED
      }

  override val reactHost: ReactHost
    get() = getDefaultReactHost(applicationContext, reactNativeHost)

  override fun onCreate() {
    super.onCreate()
    SoLoader.init(this, false)
    if (BuildConfig.IS_NEW_ARCHITECTURE_ENABLED) {
      // If you opted-in for the New Architecture, we load the native entry point for this app.
      load()
    }
  }
}
```

The package is registered by `add(NativeLocalStoragePackage())` inside `getPackages()`. The Java version of the same code is `packages.add(new NativeLocalStoragePackage());`.

## 5. Codegen and build commands

- **Android:** `cd android` then `./gradlew generateCodegenArtifactsFromSchema`. The page says this also runs automatically when the Android app is built. Example output: `BUILD SUCCESSFUL in 837ms`.
- **iOS:** `cd ios` then `bundle install` then `bundle exec pod install`. Codegen runs as a script phase that CocoaPods adds. After the pod install, open `TurboModuleExample.xcworkspace`. The page says a build from Xcode should then succeed.
- **Run:** `npm run android` or `yarn run android`; `npm run ios` or `yarn run ios`.

Other sources in these pages:
- Scaffold command: `npx @react-native-community/cli@latest init TurboModuleExample --version "0.88.0"`.
- The introduction page links to the Appendix for the list of spec types and the native types they generate.

