import XCTest

final class FlowTests: XCTestCase {
  let bid = "dev.whiskerrs.shopbench.reactnative"

  func el(_ app: XCUIApplication, _ id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
  }
  func wait(_ app: XCUIApplication, _ id: String, _ t: TimeInterval = 20, file: StaticString = #file, line: UInt = #line) -> XCUIElement {
    let e = el(app, id)
    XCTAssertTrue(e.waitForExistence(timeout: t), "missing \(id)", file: file, line: line)
    return e
  }
  func log(_ s: String) { print("FLOW: \(s)") }

  func testFullFlow() throws {
    let app = XCUIApplication(bundleIdentifier: bid)
    app.terminate()
    app.launch()
    for id in ["home-scroll", "collection-chip-0", "featured-collection", "collection-card-0", "best-seller-0", "best-seller-9", "tab-home", "tab-search", "tab-cart"] {
      _ = wait(app, id)
    }
    log("home ok; best-seller-0 label=\(el(app, "best-seller-0").label)")
    XCTAssertFalse(el(app, "cart-badge").exists)

    // Collection
    el(app, "collection-chip-0").tap()
    for id in ["product-grid", "product-card-0", "back", "sort-featured", "sort-best-selling", "sort-price-asc", "sort-price-desc"] {
      _ = wait(app, id)
    }
    let grid = el(app, "product-grid")
    var maxIdx = 0
    var stable = 0
    for _ in 0..<80 {
      grid.swipeUp(velocity: .fast)
      var newMax = maxIdx
      for i in maxIdx..<(maxIdx + 60) where el(app, "product-card-\(i)").exists { newMax = i }
      if newMax == maxIdx { stable += 1; if stable >= 4 { break } } else { stable = 0 }
      maxIdx = newMax
    }
    log("collection scrolled to end, last product-card index=\(maxIdx)")
    for s in ["sort-best-selling", "sort-price-asc", "sort-price-desc", "sort-featured"] {
      el(app, s).tap()
      let c = wait(app, "product-card-0")
      log("\(s): first=\(c.label)")
    }
    el(app, "back").tap()
    _ = wait(app, "home-scroll")

    // Featured + collection card
    el(app, "featured-collection").tap(); _ = wait(app, "product-card-0"); el(app, "back").tap()
